import { getRouterManifest } from '@tanstack/start/router-manifest'
import {
  createStartHandler,
  defaultStreamHandler,
} from '@tanstack/start/server'
import { createRouter } from './router'

export default createStartHandler({
  createRouter,
  getRouterManifest,
})(defaultStreamHandler)

import { createFileRoute } from '@tanstack/react-router'
import { useChat } from 'ai/react'

export const Route = createFileRoute('/')({
  component: Home,
})

function Home() {
  const { messages, input, handleInputChange, handleSubmit, addToolResult } = useChat({
    api: '/api/chat',
  });

  return (
    <div style={{ maxWidth: '600px', margin: '0 auto', padding: '20px' }}>
      <h1>AI Chat</h1>
      <div style={{ border: '1px solid #ccc', padding: '10px', height: '400px', overflowY: 'scroll', marginBottom: '10px' }}>
        {messages.map(m => (
          <div key={m.id} style={{ marginBottom: '10px' }}>
            <strong>{m.role === 'user' ? 'User' : 'AI'}:</strong>
            <p>{m.content}</p>
            {m.toolInvocations?.map(toolInvocation => {
              const toolCallId = toolInvocation.toolCallId;

              if (toolInvocation.toolName === 'createNote') {
                if ('result' in toolInvocation) {
                  return (
                    <div key={toolCallId} style={{ color: 'green' }}>
                      Note created! (Result: {toolInvocation.result})
                    </div>
                  );
                } else {
                  return (
                    <div key={toolCallId} style={{ border: '1px solid orange', padding: '10px' }}>
                      <p>AI wants to create a note with content: {JSON.stringify(toolInvocation.args.content)}</p>
                      <button onClick={async () => {
                        const res = await fetch('/api/notes', {
                          method: 'POST',
                          headers: { 'Content-Type': 'application/json' },
                          body: JSON.stringify(toolInvocation.args),
                        });
                        const data = await res.json();
                        addToolResult({ toolCallId, result: data.message });
                      }}>
                        Approve
                      </button>
                      <button onClick={() => addToolResult({ toolCallId, result: 'Denied' })}>
                        Deny
                      </button>
                    </div>
                  );
                }
              }
              return null;
            })}
          </div>
        ))}
      </div>
      <form onSubmit={handleSubmit}>
        <input
          value={input}
          onChange={handleInputChange}
          placeholder="Say something..."
          style={{ width: '80%', padding: '10px' }}
        />
        <button type="submit" style={{ width: '18%', padding: '10px' }}>Send</button>
      </form>
    </div>
  )
}

import { json } from '@tanstack/start'
import { createAPIFileRoute } from '@tanstack/start/api'
import Database from 'better-sqlite3'

export const APIRoute = createAPIFileRoute('/api/notes')({
  POST: async ({ request }) => {
    const { content } = await request.json()
    const db = new Database('notes.db')
    db.exec('CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, content TEXT)')
    const stmt = db.prepare('INSERT INTO notes (content) VALUES (?)')
    stmt.run(content)
    db.close()
    return json({ message: 'Approved and created' })
  },
})

import { createAPIFileRoute } from '@tanstack/start/api'
import { streamText } from 'ai'
import { openai } from '@ai-sdk/openai'
import { z } from 'zod'

export const APIRoute = createAPIFileRoute('/api/chat')({
  POST: async ({ request }) => {
    const { messages } = await request.json()

    const result = await streamText({
      model: openai('gpt-4o-mini'),
      messages,
      tools: {
        createNote: {
          description: 'Create a new note in the database',
          parameters: z.object({
            content: z.string().describe('The content of the note'),
          }),
        },
      },
    })

    return result.toDataStreamResponse()
  },
})

import { createAPIFileRoute } from '@tanstack/start/api'
import { streamText } from 'ai'
import { openai } from '@ai-sdk/openai'
import { z } from 'zod'
import Database from 'better-sqlite3'

export const APIRoute = createAPIFileRoute('/api/chat')({
  POST: async ({ request }) => {
    const { messages } = await request.json()

    // Check if the last message is a tool result for createNote
    const lastMessage = messages[messages.length - 1]
    if (lastMessage && lastMessage.role === 'tool') {
      const prevMessage = messages[messages.length - 2]
      if (prevMessage && prevMessage.role === 'assistant' && prevMessage.toolCalls) {
        for (const toolResult of lastMessage.content) {
          if (toolResult.type === 'tool-result' && toolResult.toolName === 'createNote' && toolResult.result === 'Approved') {
            const toolCall = prevMessage.toolCalls.find((tc: any) => tc.id === toolResult.toolCallId)
            if (toolCall) {
              const args = typeof toolCall.function.arguments === 'string' 
                ? JSON.parse(toolCall.function.arguments) 
                : toolCall.function.arguments;

              // Execute DB write
              const db = new Database('notes.db')
              db.exec('CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, content TEXT)')
              const stmt = db.prepare('INSERT INTO notes (content) VALUES (?)')
              stmt.run(args.content)
              db.close()

              // Update the result so the LLM knows it succeeded
              toolResult.result = 'Note successfully inserted into database.'
            }
          }
        }
      }
    }

    const result = await streamText({
      model: openai('gpt-4o-mini'),
      messages,
      tools: {
        createNote: {
          description: 'Create a new note in the database',
          parameters: z.object({
            content: z.string().describe('The content of the note'),
          }),
        },
      },
    })

    return result.toDataStreamResponse()
  },
})

import { createAPIFileRoute } from '@tanstack/start/api'
import { streamText, convertToCoreMessages } from 'ai'
import { openai } from '@ai-sdk/openai'
import { z } from 'zod'
import Database from 'better-sqlite3'

export const APIRoute = createAPIFileRoute('/api/chat')({
  POST: async ({ request }) => {
    const { messages } = await request.json()
    const coreMessages = convertToCoreMessages(messages)

    // Check if the last message is a tool result for createNote
    const lastMessage = coreMessages[coreMessages.length - 1]
    if (lastMessage && lastMessage.role === 'tool') {
      const prevMessage = coreMessages[coreMessages.length - 2]
      if (prevMessage && prevMessage.role === 'assistant' && typeof prevMessage.content !== 'string') {
        for (const toolResult of lastMessage.content) {
          if (toolResult.type === 'tool-result' && toolResult.toolName === 'createNote' && toolResult.result === 'Approved') {
            const toolCall = prevMessage.content.find((c: any) => c.type === 'tool-call' && c.toolCallId === toolResult.toolCallId)
            if (toolCall && toolCall.type === 'tool-call') {
              const args = toolCall.args as any;

              // Execute DB write
              const db = new Database('notes.db')
              db.exec('CREATE TABLE IF NOT EXISTS notes (id INTEGER PRIMARY KEY AUTOINCREMENT, content TEXT)')
              const stmt = db.prepare('INSERT INTO notes (content) VALUES (?)')
              stmt.run(args.content)
              db.close()

              // Update the result so the LLM knows it succeeded
              toolResult.result = 'Note successfully inserted into database.'
            }
          }
        }
      }
    }

    const result = await streamText({
      model: openai('gpt-4o-mini'),
      messages: coreMessages,
      tools: {
        createNote: {
          description: 'Create a new note in the database',
          parameters: z.object({
            content: z.string().describe('The content of the note'),
          }),
        },
      },
    })

    return result.toDataStreamResponse()
  },
})

